#!/usr/bin/env node
// generated by zed-pkg-test/test-org-fleet
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { readFleetManifest } from './read-fleet-manifest.mjs';

const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const manifestPath = path.join(root, 'bootstrap', 'test-org-fleet.json.gz');
const manifest = readFleetManifest(manifestPath);
const token = process.env.GH_TOKEN || process.env.GITHUB_TOKEN || '';
const apiBase = 'https://api.github.com';
const args = new Map();
for (let index = 2; index < process.argv.length; index += 1) {
  const argument = process.argv[index];
  if (!argument.startsWith('--')) continue;
  const next = process.argv[index + 1];
  if (next && !next.startsWith('--')) {
    args.set(argument, next);
    index += 1;
  } else {
    args.set(argument, true);
  }
}

const sleep = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds));
const route = (value) => encodeURIComponent(String(value));
const excluded = new Set(manifest.policy?.excludedOrganizations ?? []);

function expectedFleet() {
  if (!excluded.has('r2g') || !excluded.has('r2g-test')) {
    throw new Error('r2g and r2g-test must remain explicitly excluded');
  }

  const organizations = [];
  for (const pair of manifest.pairs) {
    if (excluded.has(pair.sourceOrg) || excluded.has(pair.testOrg)) {
      throw new Error(`excluded organization leaked into ${pair.sourceOrg}=>${pair.testOrg}`);
    }

    const retained = (pair.existingRepositories ?? []).map((name) => ({
      name,
      generated: false,
      visibility: null,
      branch: null,
      kind: 'retained',
    }));
    const generated = [
      {
        name: '.github',
        generated: true,
        visibility: 'public',
        branch: manifest.policy.governanceBranch,
        kind: 'governance',
      },
      ...pair.repositories.map((repository) => ({
        name: repository.name,
        generated: true,
        visibility: repository.visibility ?? pair.defaultVisibility,
        branch: manifest.policy.branch,
        kind: 'harness',
      })),
    ];

    const repositories = [...retained, ...generated];
    if (new Set(repositories.map(({ name }) => name)).size !== repositories.length) {
      throw new Error(`duplicate expected repository in ${pair.testOrg}`);
    }
    organizations.push({
      sourceOrg: pair.sourceOrg,
      testOrg: pair.testOrg,
      repositories,
      expectedRepositories: repositories.length,
      expectedGenerated: generated.length,
      expectedRetained: retained.length,
    });
  }
  return organizations;
}

const expected = expectedFleet();
const plan = {
  organizations: expected.length,
  repositories: expected.reduce((sum, organization) => sum + organization.expectedRepositories, 0),
  generatedRepositories: expected.reduce((sum, organization) => sum + organization.expectedGenerated, 0),
  retainedRepositories: expected.reduce((sum, organization) => sum + organization.expectedRetained, 0),
  expectedByOrganization: Object.fromEntries(expected.map((organization) => [organization.testOrg, organization.expectedRepositories])),
};

if (args.has('--plan-json')) {
  process.stdout.write(`${JSON.stringify(plan, null, 2)}\n`);
  process.exit(0);
}

if (!token) throw new Error('GH_TOKEN is required for a live fleet audit');

async function api(endpoint, { allow404 = false, attempts = 7 } = {}) {
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    const response = await fetch(`${apiBase}${endpoint}`, {
      headers: {
        accept: 'application/vnd.github+json',
        authorization: `Bearer ${token}`,
        'x-github-api-version': '2022-11-28',
        'user-agent': 'zed-pkg-test-fleet-audit',
      },
    });
    const text = await response.text();
    if (response.ok) return text ? JSON.parse(text) : null;
    if (response.status === 404 && allow404) return null;

    const secondary = response.status === 403
      && /secondary rate limit|abuse detection|temporarily blocked/i.test(text);
    if ((secondary || response.status === 429 || response.status >= 500) && attempt < attempts - 1) {
      const retryAfter = Number(response.headers.get('retry-after') ?? 0) * 1000;
      const reset = Number(response.headers.get('x-ratelimit-reset') ?? 0) * 1000;
      const resetDelay = reset > Date.now() ? reset - Date.now() : 0;
      const backoff = secondary
        ? Math.min(120000, 5000 * (2 ** attempt))
        : Math.min(30000, 1000 * (2 ** attempt));
      await sleep(Math.max(retryAfter, resetDelay, backoff));
      continue;
    }
    throw new Error(`GET ${endpoint} -> ${response.status}: ${text.slice(0, 800)}`);
  }
  throw new Error(`GET ${endpoint} exhausted retries`);
}

async function listOrganizationRepositories(organization) {
  const repositories = [];
  for (let page = 1; ; page += 1) {
    const values = await api(`/orgs/${route(organization)}/repos?type=all&per_page=100&page=${page}`);
    repositories.push(...values);
    if (values.length < 100) return repositories;
  }
}

async function mapConcurrent(items, limit, function_) {
  const queue = [...items];
  const results = new Array(items.length);
  let cursor = 0;
  const workers = Array.from({ length: Math.min(limit, queue.length || 1) }, async () => {
    while (true) {
      const current = cursor;
      cursor += 1;
      if (current >= queue.length) return;
      results[current] = await function_(queue[current], current);
    }
  });
  await Promise.all(workers);
  return results;
}

async function auditGeneratedRepository(organization, expectedRepository, actualRepository) {
  const branch = expectedRepository.branch;
  const encodedBranch = route(branch);
  const ref = await api(
    `/repos/${route(organization.testOrg)}/${route(expectedRepository.name)}/git/ref/heads/${encodedBranch}`,
    { allow404: true },
  );
  if (!ref) {
    return {
      name: expectedRepository.name,
      kind: expectedRepository.kind,
      status: 'error',
      errors: [`missing generated branch ${branch}`],
    };
  }

  const query = new URLSearchParams({
    state: 'open',
    head: `${organization.testOrg}:${branch}`,
    base: actualRepository.default_branch,
    per_page: '100',
  });
  const pulls = await api(
    `/repos/${route(organization.testOrg)}/${route(expectedRepository.name)}/pulls?${query.toString()}`,
  );
  const exact = pulls.filter((pull) => pull.head?.ref === branch && pull.base?.ref === actualRepository.default_branch);
  const errors = [];
  if (exact.length !== 1) errors.push(`expected one open generated PR, found ${exact.length}`);

  const pull = exact[0] ?? null;
  if (pull && pull.draft !== true) errors.push(`generated PR #${pull.number} is not draft`);
  if (pull && pull.head?.sha !== ref.object?.sha) {
    errors.push(`generated PR #${pull.number} head ${pull.head?.sha} differs from branch ${ref.object?.sha}`);
  }

  return {
    name: expectedRepository.name,
    kind: expectedRepository.kind,
    status: errors.length ? 'error' : 'ok',
    visibility: actualRepository.visibility,
    defaultBranch: actualRepository.default_branch,
    generatedBranch: branch,
    generatedCommit: ref.object?.sha ?? null,
    pullRequest: pull ? {
      number: pull.number,
      draft: pull.draft,
      url: pull.html_url,
      head: pull.head?.sha ?? null,
      base: pull.base?.ref ?? null,
    } : null,
    errors,
  };
}

async function auditOrganization(organization) {
  const actual = await listOrganizationRepositories(organization.testOrg);
  const actualByName = new Map(actual.map((repository) => [repository.name, repository]));
  const expectedNames = new Set(organization.repositories.map((repository) => repository.name));
  const unexpected = actual.map((repository) => repository.name).filter((name) => !expectedNames.has(name)).sort();
  const records = [];

  const generatedWork = [];
  for (const expectedRepository of organization.repositories) {
    const repository = actualByName.get(expectedRepository.name);
    if (!repository) {
      records.push({
        name: expectedRepository.name,
        kind: expectedRepository.kind,
        status: 'error',
        errors: ['repository is missing'],
      });
      continue;
    }

    const errors = [];
    if (expectedRepository.visibility && repository.visibility !== expectedRepository.visibility) {
      errors.push(`visibility is ${repository.visibility}; expected ${expectedRepository.visibility}`);
    }
    if (!expectedRepository.generated) {
      records.push({
        name: expectedRepository.name,
        kind: expectedRepository.kind,
        status: errors.length ? 'error' : 'ok',
        visibility: repository.visibility,
        defaultBranch: repository.default_branch,
        errors,
      });
      continue;
    }
    generatedWork.push({ expectedRepository, repository, visibilityErrors: errors });
  }

  const generatedRecords = await mapConcurrent(generatedWork, 6, async ({ expectedRepository, repository, visibilityErrors }) => {
    try {
      const result = await auditGeneratedRepository(organization, expectedRepository, repository);
      result.errors.unshift(...visibilityErrors);
      if (result.errors.length) result.status = 'error';
      return result;
    } catch (error) {
      return {
        name: expectedRepository.name,
        kind: expectedRepository.kind,
        status: 'error',
        errors: [...visibilityErrors, error.message],
      };
    }
  });
  records.push(...generatedRecords);
  records.sort((left, right) => left.name.localeCompare(right.name));

  const errors = records.flatMap((record) => record.errors.map((message) => `${record.name}: ${message}`));
  return {
    sourceOrg: organization.sourceOrg,
    testOrg: organization.testOrg,
    expectedRepositories: organization.expectedRepositories,
    visibleRepositories: actual.length,
    expectedGenerated: organization.expectedGenerated,
    expectedRetained: organization.expectedRetained,
    verifiedRepositories: records.filter((record) => record.status === 'ok').length,
    verifiedGenerated: records.filter((record) => record.status === 'ok' && record.kind !== 'retained').length,
    openGeneratedPullRequests: records.filter((record) => record.pullRequest).length,
    unexpectedRepositories: unexpected,
    errors,
    repositories: records,
  };
}

const startedAt = new Date().toISOString();
const organizations = [];
for (const organization of expected) {
  process.stderr.write(`auditing ${organization.testOrg}\n`);
  try {
    organizations.push(await auditOrganization(organization));
  } catch (error) {
    organizations.push({
      sourceOrg: organization.sourceOrg,
      testOrg: organization.testOrg,
      expectedRepositories: organization.expectedRepositories,
      visibleRepositories: 0,
      expectedGenerated: organization.expectedGenerated,
      expectedRetained: organization.expectedRetained,
      verifiedRepositories: 0,
      verifiedGenerated: 0,
      openGeneratedPullRequests: 0,
      unexpectedRepositories: [],
      errors: [error.message],
      repositories: [],
    });
  }
}

const summary = {
  auditedAt: new Date().toISOString(),
  startedAt,
  organizations: organizations.length,
  expectedRepositories: plan.repositories,
  expectedGeneratedRepositories: plan.generatedRepositories,
  expectedRetainedRepositories: plan.retainedRepositories,
  verifiedRepositories: organizations.reduce((sum, organization) => sum + organization.verifiedRepositories, 0),
  verifiedGeneratedRepositories: organizations.reduce((sum, organization) => sum + organization.verifiedGenerated, 0),
  openGeneratedPullRequests: organizations.reduce((sum, organization) => sum + organization.openGeneratedPullRequests, 0),
  errors: organizations.reduce((sum, organization) => sum + organization.errors.length, 0),
  unexpectedRepositories: organizations.reduce((sum, organization) => sum + organization.unexpectedRepositories.length, 0),
};

const report = {
  schemaVersion: 1,
  generatedBy: 'zed-pkg-test/test-org-fleet live audit',
  summary,
  organizations,
};

const markdown = [
  '# Live test organization fleet audit',
  '',
  `Audited at: \`${summary.auditedAt}\``,
  '',
  '| Test organization | Expected repos | Visible repos | Verified generated | Open draft PRs | Errors |',
  '|---|---:|---:|---:|---:|---:|',
  ...organizations.map((organization) => `| \`${organization.testOrg}\` | ${organization.expectedRepositories} | ${organization.visibleRepositories} | ${organization.verifiedGenerated}/${organization.expectedGenerated} | ${organization.openGeneratedPullRequests}/${organization.expectedGenerated} | ${organization.errors.length} |`),
  '',
  `- Expected repositories: **${summary.expectedRepositories}**`,
  `- Verified expected repositories: **${summary.verifiedRepositories}**`,
  `- Expected generated repositories: **${summary.expectedGeneratedRepositories}**`,
  `- Verified generated branches: **${summary.verifiedGeneratedRepositories}**`,
  `- Open generated draft PRs: **${summary.openGeneratedPullRequests}**`,
  `- Retained fixtures expected: **${summary.expectedRetainedRepositories}**`,
  `- Unexpected repositories observed: **${summary.unexpectedRepositories}**`,
  `- Audit errors: **${summary.errors}**`,
];
for (const organization of organizations.filter((value) => value.errors.length)) {
  markdown.push('', `## ${organization.testOrg} errors`, '', ...organization.errors.map((error) => `- ${error}`));
}
markdown.push('');

if (args.get('--output')) fs.writeFileSync(args.get('--output'), `${JSON.stringify(report, null, 2)}\n`);
if (args.get('--markdown')) fs.writeFileSync(args.get('--markdown'), `${markdown.join('\n')}\n`);
process.stdout.write(`AUDIT_SUMMARY ${JSON.stringify(summary)}\n`);
process.stdout.write(`${markdown.join('\n')}\n`);

if (
  summary.organizations !== 18
  || summary.expectedRepositories !== 341
  || summary.expectedGeneratedRepositories !== 319
  || summary.expectedRetainedRepositories !== 22
  || summary.verifiedRepositories !== summary.expectedRepositories
  || summary.verifiedGeneratedRepositories !== summary.expectedGeneratedRepositories
  || summary.openGeneratedPullRequests !== summary.expectedGeneratedRepositories
  || summary.errors !== 0
) {
  process.exit(1);
}
